Caveman mode: **full**

---

Three parts: class component, fallback UI, usage.

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Log here — swap console for Sentry/Datadog/etc.
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      return fallback
        ? fallback(error, this.reset)
        : <DefaultFallback error={error} reset={this.reset} />;
    }

    return children;
  }
}
```

```tsx
// DefaultFallback.tsx
interface FallbackProps {
  error: Error;
  reset: () => void;
}

function DefaultFallback({ error, reset }: FallbackProps) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    background: "#fef2f2",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title:  { margin: "0 0 .5rem", color: "#b91c1c" },
  message: { fontSize: ".85rem", color: "#7f1d1d", whiteSpace: "pre-wrap" as const },
  button: {
    marginTop: "1rem",
    padding: ".5rem 1.25rem",
    background: "#b91c1c",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
  },
} as const;
```

```tsx
// Usage
// 1. Default fallback
<ErrorBoundary>
  <BrokenComponent />
</ErrorBoundary>

// 2. Custom fallback
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
>
  <BrokenComponent />
</ErrorBoundary>

// 3. With external logger
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <BrokenComponent />
</ErrorBoundary>
```

---

**Key points:**

- `getDerivedStateFromError` — static, sets state, triggers fallback render
- `componentDidCatch` — side effects only (logging). Not for state
- `reset` clears error → children remount fresh
- `fallback` prop = render prop pattern, full control over UI
- Wrap at route level + around risky widgets (data-fetch heavy, third-party)

**Caveat:** Boundaries catch render/lifecycle errors only. Async errors (event handlers, `setTimeout`, promises) need `try/catch` or `window.onerror`.
